const form=document.getElementById("laminateForm"),result=document.getElementById("result"),material=document.getElementById("material");function toggleFields(){const e=document.getElementById("lamFields"),t=document.getElementById("linoFields");if(!e||!t)return;const a=material&&material.value==="laminate";e.style.display=a?"":"none",t.style.display=a?"none":""}material&&material.addEventListener("change",toggleFields),toggleFields(),form&&form.addEventListener("submit",e=>{e.preventDefault();const t=parseFloat(document.getElementById("length").value)||0,a=parseFloat(document.getElementById("width").value)||0,i=parseFloat(document.getElementById("reserve").value)||0;if(t<=0||a<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите длину и ширину комнаты больше нуля.</p>';return}const o=t*a;if(material&&material.value==="laminate"){const s=parseFloat(document.getElementById("boardL").value)||0,n=parseFloat(document.getElementById("boardW").value)||0,l=parseInt(document.getElementById("perPack").value,10)||0;if(s<=0||n<=0||l<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите размеры доски и количество досок в упаковке.</p>';return}const c=s/1e3*(n/1e3),r=Math.ceil(o*(1+i/100)/c),d=Math.ceil(r/l);result.innerHTML=`
        <div class="result-list">
          <div class="item"><span>Площадь комнаты</span><span class="val">${fmt(o)} м²</span></div>
          <div class="item"><span>Площадь доски</span><span class="val">${fmt(c)} м²</span></div>
          <div class="item"><span>Досок (с запасом ${fmt(i)}%)</span><span class="val">${fmt(r)} шт</span></div>
          <div class="item total"><span>Упаковок (по ${l} шт)</span><span class="val">${fmt(d)} уп.</span></div>
        </div>
      `}else{const s=parseFloat(document.getElementById("rollW").value)||0;if(s<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите ширину рулона больше нуля.</p>';return}const n=Math.ceil(a/s),l=n*t;result.innerHTML=`
        <div class="result-list">
          <div class="item"><span>Площадь комнаты</span><span class="val">${fmt(o)} м²</span></div>
          <div class="item"><span>Полос (по ширине рулона ${fmt(s)} м)</span><span class="val">${fmt(n)} шт</span></div>
          <div class="item total"><span>Погонных метров (с запасом ${fmt(i)}%)</span><span class="val">${fmt(l)} м</span></div>
        </div>
      `}});function fmt(e){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(e)}
